import 'package:cloud_firestore/cloud_firestore.dart';import 'package:flutter/material.dart';class AnnouncementsAdminPage extends StatefulWidget{const AnnouncementsAdminPage({super.key});@override State<AnnouncementsAdminPage> createState()=>_A();}class _A extends State<AnnouncementsAdminPage>{final title=TextEditingController(),body=TextEditingController();Future<void> send()async{if(title.text.isEmpty)return;await FirebaseFirestore.instance.collection('announcements').add({'title':title.text,'body':body.text,'active':true,'createdAt':FieldValue.serverTimestamp()});title.clear();body.clear();if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Pengumuman dikirim realtime')));}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Pengumuman Pengguna')),body:Padding(padding:const EdgeInsets.all(20),child:Column(children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Judul pengumuman')),TextField(controller:body,maxLines:4,decoration:const InputDecoration(labelText:'Isi pengumuman')),const SizedBox(height:16),FilledButton.icon(onPressed:send,icon:const Icon(Icons.send),label:const Text('Kirim ke semua pengguna'))])));}}